import requests
from bs4 import BeautifulSoup

def scrape_website(url):
    page = requests.get(url)
    soup = BeautifulSoup(page.content, 'html.parser')

    for link in soup.find_all('a'):
        href = link.get('href')

        if href.startswith('http'):
            scrape_website(href)

